# De-duplicate names defensively inside this cohort
seen = set()
unique_players = []
for p in INDIAN_DOMESTIC_RAW:
    norm = p[0].strip().lower()
    if norm not in seen:
        seen.add(norm)
        unique_players.append(p)

print(f"Staged {len(unique_players)} Indian domestic players.")

OBJECTS = []
for idx, item in enumerate(unique_players, 1):
    fullName, displayName, role, batHand, bowlStyle, isWk, debut, retYear, active, comps, fc, la, t20, elite = item
    pid = make_uuid(3, idx)
    cricId = f"ind_dom_{make_slug(fullName)}"
    stats = make_domestic_stats(role, isWk, fc, la, t20, elite)
    
    OBJECTS.append({
        "id": pid,
        "fullName": fullName,
        "displayName": displayName,
        "country": "India",
        "role": role,
        "batHand": batHand,
        "bowlStyle": bowlStyle,
        "isWk": isWk,
        "debutYear": debut,
        "retYear": retYear,
        "active": active,
        "category": "DOMESTIC_ONLY",
        "domOnly": True,
        "comps": comps,
        "cricId": cricId,
        "stats": stats,
    })

write_cohort("cohort-domestic-india.ts", "COHORT_DOMESTIC_INDIA", OBJECTS)
